-- CIS Self-Describing Fact Table
-- Target: MySQL 8.0.32
-- Table: sn_cis_integration_competition_wide
-- Grain: one row per device; unique identity = manufacturer + platform + device_type + device_model.
-- Semantic version: cis-integration-v4.
-- Top-level total: integration_total = small_system_total + peripheral_total + wireless_total.
-- When deriving integration_total, missing top-level domain values are treated as 0 per the confirmed source rule.
-- Wireless total is a source-reported top-level value covering RF and NC; do not force RF + NC = wireless total.
-- Antenna is a cross-cutting physical-hardware view across RF/NC, not a third additive wireless domain.
-- Module totals, parent totals, composite values, and detail areas must not be added across overlapping hierarchy levels.
-- Scheme labels: XRZ=仙人掌; FXZ=风信子; PGY=蒲公英. GG is retained as a raw scheme code; its Chinese name and exact scheme mapping are unconfirmed.
-- Area columns use VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin: one numeric observation is stored as one numeric string; repeated observations for the same logical field are joined with commas in source order (e.g. 42.77,16.59). Never SUM, average, overwrite or deduplicate repeated observations. NULL means not provided/unknown/not applicable; it is not zero.
-- MongoDB length audit: 15 target devices; 267 area columns; maximum observed area value length=11 characters; two multivalue cells.
-- Area VARCHAR(16) provides 5 characters of headroom beyond the observed maximum.
-- device_pic_url VARCHAR(96) is based on the observed maximum of 55 characters.
-- Declared row-size estimate: 7013 bytes with DATETIME(3), below the 8126-byte InnoDB limit; ROW_FORMAT=DYNAMIC.
-- raw_value_annotations preserves original text for area fields; device_design_attributes preserves non-area board/design attributes.

CREATE TABLE `sn_cis_integration_competition_wide` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '代理主键；每条记录对应一台设备的CIS集成度事实记录。',
  `manufacturer` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '设备厂商名称；设备身份唯一键组成部分。',
  `platform` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '芯片平台/平台代号；设备身份唯一键组成部分。',
  `device_type` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '设备类型，例如phone；设备身份唯一键组成部分。',
  `device_model` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '设备型号；设备身份唯一键组成部分。',
  `release_date` DATETIME(3) NULL COMMENT '设备发布时间；统一存储为UTC时间。',
  `release_date_text` VARCHAR(64) NULL COMMENT '无法规范化为日期时间时保留的原始发布时间文本。',
  `device_pic_url` VARCHAR(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '设备图片地址；用于设备识别和前端展示，不参与集成面积计算。',
  `source_document_id` CHAR(24) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '来源MongoDB integration_device文档的ObjectId十六进制值；仅用于数据追溯，不参与业务分类、汇总或面积计算。',
  `area_unit` VARCHAR(16) NOT NULL DEFAULT '平方毫米' COMMENT '本表所有集成面积及面积汇总字段的统一单位。',
  `semantic_version` VARCHAR(32) NOT NULL DEFAULT 'cis-integration-v4' COMMENT '本行采用的CIS统一业务语义树版本；字段路径、业务定义或汇总口径变更时升级。当前DDL版本为cis-integration-v4。',
  `integration_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：整机；业务定义：按已确认口径：小系统总计 + 外设总计 + 无线总计。若由三大域派生，空值按0参与计算；仅当三个域均为单值文本时才允许派生；任一域为逗号分隔多值时不得求和派生；若来源直接提供整机总计，优先保留来源值。；数据层级：L0整机总计；统计规则：唯一整机顶层指标；禁止与任何下级业务域、模块汇总或子模块面积相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `small_system_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统；业务定义：来源提供的小系统总面积；范围包含Modem、PMK、PMU、SOC模块总计、UFS模块总计等。SOC/UFS父级总计不可再与下级明细重复求和。；数据层级：L1顶层业务域汇总；统计规则：作为integration_total三大组成域之一；不得再加SOC、UFS及其他小系统子模块汇总。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `peripheral_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：外设；业务定义：来源提供的外设总面积。不得通过将peripheral_composite、camera、audio、display、NFC、sensor、interface、charger等分析字段直接求和来替代。；数据层级：L1顶层业务域汇总；统计规则：作为integration_total三大组成域之一；复合外设项及其他模块视图可能覆盖其范围，不可重复累加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `wireless_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：无线；业务定义：来源提供的无线总面积，业务域包含RF与NC；该字段是无线顶层权威汇总值，不强制等于RF总计+NC总计。；数据层级：L1顶层业务域汇总；统计规则：作为integration_total三大组成域之一；不得与RF、NC、天线、NFC、射频前端或无线子模块汇总重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `wireless_rf_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：无线 → RF；业务定义：来源提供的RF子域总面积；按射频电路功能归类，包含蜂窝射频及明确归入RF的卫星射频链路。天线是跨NC/RF物理视图，不据此推定其已包含或未包含在RF值中。；数据层级：L2无线子域汇总；统计规则：来源汇总值；不由RF前端、卫星方案或RF明细自动求和；不得与wireless_total或wireless_rf_frontend_total重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `wireless_nc_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：无线 → NC；业务定义：来源提供的NC非蜂窝无线子域总面积；NC视图包括Wi-Fi/BT、UWB、Connectivity、NFC及经确认的非蜂窝定位/通信功能。；数据层级：L2无线子域汇总；统计规则：来源汇总值；不由UWB、Wi-Fi/BT、NFC、Connectivity或天线明细自动求和；不得与wireless_total或其子模块汇总重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `camera_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：摄像头 → CAM；业务定义：摄像头模块汇总值；FRONT_CAM/FRONT_CAMERA、REAR_CAM1/REAR_CAMERA1、REAR_CAM2/REAR_CAMERA2疑似别名。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；别名未确认互斥前不得按所有明细求和；也不得与peripheral_composite或peripheral_total重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `fpc_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：连接与接口 → FPC；业务定义：FPC模块汇总值，覆盖FPC接口及NTC相关主FPC接口支路。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；不得与FPC子模块或其他业务域总计重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `io_expansion_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：连接与接口 → IO扩展；业务定义：IO扩展模块汇总值，对应IODIE及相关输入输出扩展功能。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；不得与IODIE明细重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `wireless_nc_nfc_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：无线 → NC → NFC；业务定义：NFC模块汇总值，涉及NFC、NFC_110T及NFC_FE相关电路；NFC_FE是否为NFC父模块内含部分，以来源定义为准。；数据层级：NC下级模块汇总视图；统计规则：属于NC下级视图；不得与wireless_nc_total或NFC子模块明细重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `pmu_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：电源管理 → PMU；业务定义：PMU模块汇总值，覆盖PMU0/PMU1/PMU2的BUCK、LDO、数字时钟等子模块；小系统下PMU1/PMU2是另一业务路径。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；通道、实例及小系统PMU字段未确认互斥前，不从明细自动SUM。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `scharger_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：电源管理 → Scharger；业务定义：来源提供的Scharger模块汇总值，对应CHARGER_RES、CHARGER2、副Charger、Buck_Charger、SC1/SC2、Scharger_V510及WL_Charger等条目。外设Scharge/Wcharge为独立字段；WL_Charger与Wcharge可能重叠。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；CHARGER_RES大小写变体、外设Scharge/Wcharge与WL_Charger不得未经确认直接相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `sensor_lowercase_group_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：传感器 → sensor（小写模块标识）；业务定义：原始模块标识为小写sensor的传感器汇总值；与大写SENSOR模块的统计范围未确认，故独立保存。；数据层级：模块级汇总视图；统计规则：不得与sensor_uppercase_group_total或其明细自动合并/相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `sensor_uppercase_group_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：传感器 → SENSOR（大写模块标识）；业务定义：大写SENSOR模块汇总值，涉及环境光/接近及SAR子模块；环境光/接近与SAR命名存在疑似别名/包含关系。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；疑似别名或父子项未确认互斥前，不从明细自动SUM，也不得与小写sensor组总计相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `sim_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：连接与接口 → SIM；业务定义：SIM模块汇总值，涉及SIM_main、SIM_SD及SIM_SD_IOEXP；后两者可能存在接口/IO扩展父子关系。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；不得与SIM明细或测试点中的SIM_LGA_Point重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `test_point_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：测试与调试 → 测试点；业务定义：测试点模块汇总值，涉及SIM_LGA_Point、Test_point、Test_Point及屏蔽结构；Test_point与Test_Point疑似别名。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；别名及SIM_LGA_Point跨域重叠未确认前，不从明细自动SUM。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `storage_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：存储；业务定义：独立存储模块汇总值，对应存储分支下的memory；与小系统→UFS→Memory是不同业务路径。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；不得与small_system_ufs_total或small_system_ufs_memory自动合并/相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `battery_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：电源管理 → 电池；业务定义：电池模块汇总值，涉及Battery、Battery_Main、电池保护及BJEH（贝加尔湖）；Battery_BJEH与BJEH可能重叠。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；Battery_BJEH与BJEH未确认互斥前不得同时相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `analog_phy_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：连接与接口 → 模拟PHY；业务定义：模拟PHY模块汇总值，涉及USB接口及保护电路；USB_Protection与USB_protection疑似大小写别名。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；USB保护别名未确认互斥前不得从明细自动SUM。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `wireless_rf_frontend_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：无线 → RF → 射频前端；业务定义：射频前端模块汇总值，覆盖PA、PAMID、RF Switch、LNA、TRX及相关供电/跟踪电路；不等同于全部RF域总计。；数据层级：RF下级模块汇总视图；统计规则：不得与wireless_rf_total、卫星方案汇总、天线汇总或射频前端明细重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `wireless_antenna_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：无线 → 天线（跨NC/RF物理硬件视图）；业务定义：来源提供的天线硬件汇总值；天线可能服务于蜂窝、Wi-Fi/NC、UWB、GNSS或卫星通信。side_ANT已归入天线候选；LDS_ant含义仍待确认，不假设候选值已包含在来源天线总计中。；数据层级：跨域硬件汇总视图；统计规则：不是无线下第三个可加总业务域；不得额外加到wireless_total、wireless_rf_total或wireless_nc_total，也不得与天线明细重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `temperature_detection_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：传感器 → 温度检测（原始分组，业务归属待确认）；业务定义：来源中名为温度检测的分组汇总值，但明细为Key/KEY，现有定义不足以确认它们属于温度传感器。；数据层级：原始分组汇总视图；统计规则：保留来源值；Key/KEY归属确认前，不用于温度传感器专项分析或与其他传感器总计相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `display_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：显示；业务定义：显示模块汇总值，涉及Display_INTERFACE、Display_PWR、LCD、MLCD/MSLCD及供电/旁路；LCD、LCD_Power、Display_PWR可能存在父子/覆盖关系。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；不得与display_lcd_driver_power或显示子模块明细重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `audio_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：音频；业务定义：音频模块汇总值，涉及Codec、SmartPA、耳机/麦克风/振动及旁路；SmartPA父子项及相近MIC/VIB命名可能重叠。；数据层级：模块级汇总视图；统计规则：保留来源汇总值；不得与peripheral_composite、audio_codec、SmartPA父子项或疑似别名重复相加。；指标定义：单台设备在该业务路径/层级下的集成面积汇总；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `small_system_modem_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → Modem；业务定义：蜂窝通信调制解调器/基带通信子系统。；原始子模块：Modem；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `small_system_modem_pmu_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → Modem PMU；业务定义：Modem 子系统的电源管理单元或供电电路。；原始子模块：Modem PMU；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `small_system_pmk_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → PMK；业务定义：小系统中的 PMK 模块代号；仅凭名称无法可靠展开，需业务同事确认。；原始子模块：PMK；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `small_system_pmu1_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → PMU1；业务定义：第 1 组电源管理单元（PMU）或其供电子系统。；原始子模块：PMU1；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。业务边界提示：与电源管理→PMU下的同编号通道分列，不按编号直接合并。；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `small_system_pmu2_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → PMU2；业务定义：第 2 组电源管理单元（PMU）或其供电子系统。；原始子模块：PMU2；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。业务边界提示：与电源管理→PMU下的同编号通道分列，不按编号直接合并。；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `small_system_rfic_pmu_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → RFIC PMU；业务定义：射频集成电路（RFIC）的电源管理单元/供电电路。；原始子模块：RFIC PMU；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。业务边界提示：小系统路径下的RFIC PMU与无线RF路径下的RFIC_PMU分列保存，不因名称相近而合并或相加。；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `small_system_soc_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → SOC（模块父级汇总）；业务定义：系统级芯片（SoC）及其相关集成电路。；原始子模块：SOC；数据层级：模块父级汇总；指标定义：单台设备SOC模块汇总面积，包含SOC_GND、SOC_GPIO_interface、SOC_HS_interface、SOC_PWR1至4；统计规则：来源父级汇总，不与下级明细或small_system_total重复相加；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `small_system_ufs_total_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：小系统 → UFS（模块父级汇总）；业务定义：通用闪存存储（UFS）子系统。；原始子模块：UFS；数据层级：模块父级汇总；指标定义：单台设备小系统下UFS模块汇总面积，包含小系统→UFS→Memory；统计规则：来源父级汇总，不与Memory明细或small_system_total重复相加；单位：平方毫米；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `peripheral_composite_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：外设 → 外设综合统计项；业务定义：外设综合统计项，涵盖摄像头供电、闪光灯、麦克风/振动、SmartPA、NFC、传感器、接口及低压特性等。；原始子模块：CAM_PWR/闪光灯/MIC_VIB/SmartPA/NFC/sensor/接口/低压特性等；数据层级：复合统计值；指标定义：来源将摄像头供电、闪光灯、MIC/VIB、SmartPA、NFC、传感器、接口及低压特性合并统计的面积；统计规则：不可拆分或与覆盖范围内的独立模块/汇总相加；单位：平方毫米；业务边界提示：复合统计项覆盖摄像头供电、闪光灯、MIC/VIB、SmartPA、NFC、传感器、接口和低压特性；不得与覆盖范围内的独立模块或汇总相加。；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。',
  `power_charger_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：电源管理 → Charger；业务定义：充电器或充电管理相关电路。；原始子模块：Charger；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `audio_codec_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：音频 → Codec；业务定义：音频编解码器（Audio Codec）。；原始子模块：codec；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `display_lcd_driver_power_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：显示 → LCD驱动/电源；业务定义：LCD 显示驱动及供电电路。；原始子模块：LCD 驱动/电源；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `power_scharger_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：电源管理 → 充电管理相关电路 → Scharge（统计边界待确认）；业务定义：Scharger 充电相关电路；具体统计范围待确认。；原始子模块：Scharge；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。业务边界提示：与Scharger模块组可能重叠；未确认前不并入Scharger总计。；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
  `power_wireless_charger_area_mm2` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '业务路径：电源管理 → 无线充电 → Wcharge；业务定义：无线充电相关电路。；原始子模块：Wcharge；数据层级：面积明细；指标定义：单台设备该模块/子模块的PCB集成面积；单位：平方毫米；多值规则：同字段多条来源值按原始顺序以英文逗号拼接（如42.77,16.59），不求和、平均、覆盖或去重；父子层级不可混算。业务边界提示：与Scharger组下WL_Charger可能重叠，不自动合并。；NULL表示未提供/未知/不适用，不代表0；0表示明确记录为零。',
